def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

count = 0
for number in range(2, 10000):
    if is_prime(number):
        count += 1

print(f"The number of prime numbers below 10,000 is: {count}")
